<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Registration</title>
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
body{font-family:system-ui,-apple-system,sans-serif;background:#e8ecf1;color:#1a1a2e;min-height:100vh;display:flex;flex-direction:column}
header{background:#0b1d3a;color:#fff;padding:1rem 1.5rem;width:100%}
header h1{font-size:1.25rem;font-weight:600;letter-spacing:.02em}
header .accent{color:#e87722}
main{flex:1;display:flex;justify-content:center;padding:2rem 1rem}
.panel{background:#fff;border-radius:8px;box-shadow:0 2px 12px rgba(0,0,0,.08);padding:2rem;width:100%;max-width:640px}
.panel h2{font-size:1.5rem;margin-bottom:.25rem;color:#0b1d3a}
.panel p.sub{font-size:.9rem;color:#555;margin-bottom:1.5rem}
.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem 1.5rem}
.full{grid-column:1/-1}
label{display:block;font-size:.875rem;font-weight:600;margin-bottom:.3rem;color:#0b1d3a}
input[type="text"],input[type="email"],input[type="date"],input[type="password"]{width:100%;padding:.55rem .75rem;border:1px solid #b0bec5;border-radius:4px;font-size:1rem;transition:border-color .15s}
input:focus{outline:none;border-color:#e87722;box-shadow:0 0 0 2px rgba(232,119,34,.2)}
input.invalid{border-color:#c62828}
.error-msg{font-size:.8rem;color:#c62828;margin-top:.25rem;min-height:1.1em}
.pw-wrap{position:relative}
.pw-wrap input{padding-right:2.5rem}
.toggle-pw{position:absolute;right:.5rem;top:50%;transform:translateY(-50%);background:none;border:none;cursor:pointer;font-size:.8rem;color:#0b1d3a;padding:.25rem .35rem;border-radius:3px}
.toggle-pw:hover,.toggle-pw:focus{background:#e8ecf1;outline:none}
.checkbox-row{display:flex;align-items:flex-start;gap:.5rem;margin-top:.25rem}
.checkbox-row input{margin-top:.2rem;width:auto}
.checkbox-row label{font-weight:400;font-size:.875rem;margin-bottom:0}
.btn-submit{display:inline-block;background:#e87722;color:#fff;border:none;padding:.7rem 2rem;font-size:1rem;font-weight:600;border-radius:4px;cursor:pointer;margin-top:.5rem;transition:background .15s}
.btn-submit:hover,.btn-submit:focus{background:#cf6518;outline:none;box-shadow:0 0 0 3px rgba(232,119,34,.3)}
.btn-submit:disabled{opacity:.6;cursor:not-allowed}
.success-banner{background:#e8f5e9;border:1px solid #a5d6a7;color:#2e7d32;padding:1rem;border-radius:4px;margin-bottom:1rem;font-weight:600;text-align:center}
