<div class="form-grid">
<div>
<label for="username">Username</label>
<input type="text" id="username" name="username" autocomplete="username" required aria-describedby="usernameErr">
<div class="error-msg" id="usernameErr" role="alert"></div>
</div>
<div>
<label for="email">Email Address</label>
<input type="email" id="email" name="email" autocomplete="email" required aria-describedby="emailErr">
<div class="error-msg" id="emailErr" role="alert"></div>
</div>
<div>
<label for="dob">Date of Birth <span style="font-weight:400;color:#777">(optional)</span></label>
<input type="date" id="dob" name="dob" autocomplete="bday" aria-describedby="dobErr">
<div class="error-msg" id="dobErr" role="alert"></div>
</div>
<div></div>
<div>
<label for="password">Password</label>
<div class="pw-wrap">
<input type="password" id="password" name="new-password" autocomplete="new-password" required aria-describedby="pwErr">
<button type="button" class="toggle-pw" id="pwToggle" aria-label="Show password">Show</button>
</div>
<div class="error-msg" id="pwErr" role="alert"></div>
</div>
<div>
<label for="confirmPw">Confirm Password</label>
<div class="pw-wrap">
<input type="password" id="confirmPw" name="confirm-password" autocomplete="new-password" required aria-describedby="cpwErr">
</div>
<div class="error-msg" id="cpwErr" role="alert"></div>
</div>
<div class="full checkbox-row">
<input type="checkbox" id="tos" name="tos" required aria-describedby="tosErr">
<label for="tos">I accept the <strong>Terms of Service</strong> and <strong>Privacy Policy</strong></label>
</div>
<div class="full"><div class="error-msg" id="tosErr" role="alert"></div></div>
<div class="full">
<button type="submit" class="btn-submit" id="submitBtn">Register</button>
</div>
</div>
