(function(){
var STORAGE_KEY='registered_accounts_v2';
function getUsers(){try{return JSON.parse(localStorage.getItem(STORAGE_KEY))||[]}catch(e){return[]}}
function saveUser(u){var users=getUsers();users.push(u);localStorage.setItem(STORAGE_KEY,JSON.stringify(users))}

var form=document.getElementById('regForm');
var successMsg=document.getElementById('successMsg');
var alertSummary=document.getElementById('alertSummary');
var pwInput=document.getElementById('password');
var cpwInput=document.getElementById('confirmPw');
var pwToggle=document.getElementById('pwToggle');

var fieldMap={
username:{el:document.getElementById('username'),err:document.getElementById('usernameErr')},
email:{el:document.getElementById('email'),err:document.getElementById('emailErr')},
dob:{el:document.getElementById('dob'),err:document.getElementById('dobErr')},
password:{el:pwInput,err:document.getElementById('pwErr')},
confirmPassword:{el:cpwInput,err:document.getElementById('cpwErr')},
terms:{el:document.getElementById('tos'),err:document.getElementById('tosErr')}
};

function setError(key,msg){
var f=fieldMap[key];
f.err.textContent=msg;
if(msg){f.el.classList.add('invalid');f.el.setAttribute('aria-invalid','true')}
else{f.el.classList.remove('invalid');f.el.removeAttribute('aria-invalid')}
}

function clearErrors(){
Object.keys(fieldMap).forEach(function(k){setError(k,'')});
alertSummary.hidden=true;alertSummary.textContent='';
}

function showSummary(msg){
alertSummary.textContent=msg;
alertSummary.hidden=false;
}

function validateUsername(v){
if(!v)return'Username is required.';
if(v.length<3)return'Username must be at least 3 characters.';
if(v.length>20)return'Username must be at most 20 characters.';
if(!/^[a-zA-Z]/.test(v))return'Username must start with a letter.';
if(!/^[a-zA-Z][a-zA-Z0-9_]*$/.test(v))return'Username may only contain letters, digits, or underscores.';
return'';
}

function validateEmail(v){
if(!v)return'Email is required.';
if(/\s/.test(v))return'Email must not contain whitespace.';
var parts=v.split('@');
if(parts.length!==2)return'Email must contain exactly one @ sign.';
var local=parts[0],domain=parts[1];
if(!local)return'Email local part is required.';
if(local.charAt(0)==='.'||local.charAt(local.length-1)==='.')return'Email local part must not start or end with a dot.';
if(/\.\./.test(local))return'Email local part must not contain repeated dots.';
if(!domain)return'Email domain is required.';
var labels=domain.split('.');
if(labels.length<2)return'Email domain must have at least two labels.';
for(var i=0;i<labels.length;i++){
var lb=labels[i];
if(!lb)return'Email domain must not have empty labels.';
if(lb.charAt(0)==='-'||lb.charAt(lb.length-1)==='-')return'Email domain labels must not start or end with a hyphen.';
}
return'';
}

function validatePassword(v){
if(!v)return'Password is required.';
if(v.length<10)return'Password must be at least 10 characters.';
if(v.length>64)return'Password must be at most 64 characters.';
if(!/[a-zA-Z]/.test(v))return'Password must contain at least one letter.';
if(!/[0-9]/.test(v))return'Password must contain at least one digit.';
return'';
}

function validateDob(v){
if(!v)return'';
if(!/^\d{4}-\d{2}-\d{2}$/.test(v))return'Enter a valid date in YYYY-MM-DD format.';
var parts=v.split('-');
var y=parseInt(parts[0],10),m=parseInt(parts[1],10),d=parseInt(parts[2],10);
var dt=new Date(y,m-1,d);
if(dt.getFullYear()!==y||dt.getMonth()!==m-1||dt.getDate()!==d)return'Enter a valid calendar date.';
return'';
}

function runValidation(isSubmit){
clearErrors();
var errors=[];
var uRaw=fieldMap.username.el.value;
var uTrim=uRaw.trim();
var uErr=validateUsername(uTrim);
if(uErr){setError('username',uErr);errors.push('username')}

var eRaw=fieldMap.email.el.value.trim();
var eNorm=eRaw.toLowerCase();
var eErr=validateEmail(eNorm);
if(eErr){setError('email',eErr);errors.push('email')}

var dVal=fieldMap.dob.el.value;
var dErr=validateDob(dVal);
if(dErr){setError('dob',dErr);errors.push('dob')}

var pVal=fieldMap.password.el.value;
var pErr=validatePassword(pVal);
if(pErr){setError('password',pErr);errors.push('password')}

var cpVal=fieldMap.confirmPassword.el.value;
if(!cpVal){setError('confirmPassword','Please confirm your password.');errors.push('confirmPassword')}
else if(cpVal!==pVal){setError('confirmPassword','Passwords do not match.');errors.push('confirmPassword')}

if(!fieldMap.terms.el.checked){setError('terms','You must accept the Terms of Service.');errors.push('terms')}

if(errors.length===0){
var users=getUsers();
var dupUser=false,dupEmail=false;
for(var i=0;i<users.length;i++){
if(users[i].username.toLowerCase()===uTrim.toLowerCase())dupUser=true;
if(users[i].email===eNorm)dupEmail=true;
}
if(dupUser){setError('username','This username is already registered.');errors.push('username')}
if(dupEmail){setError('email','An account with this email already exists.');errors.push('email')}
}

if(errors.length>0){
showSummary('There is a problem with your input. Please correct the errors below.');
var firstKey=errors[0];
fieldMap[firstKey].el.focus();
return false;
}
return{username:uTrim,email:eNorm,dob:dVal};
}

form.addEventListener('submit',function(ev){
ev.preventDefault();
successMsg.hidden=true;
var result=runValidation(true);
if(result===false)return;
saveUser({username:result.username,email:result.email,dob:result.dob});
successMsg.hidden=false;
alertSummary.hidden=true;
form.reset();
clearErrors();
fieldMap.username.el.focus();
});

['username','email','dob','password','confirmPassword'].forEach(function(k){
fieldMap[k].el.addEventListener('blur',function(){
var res=runValidation(false);
if(res!==false){successMsg.hidden=false;alertSummary.hidden=true}
});
fieldMap[k].el.addEventListener('input',function(){
if(fieldMap[k].err.textContent){
var res=runValidation(false);
if(res!==false){successMsg.hidden=false;alertSummary.hidden=true}
}
});
});
fieldMap.terms.el.addEventListener('change',function(){
if(fieldMap.terms.err.textContent){
var res=runValidation(false);
if(res!==false){successMsg.hidden=false;alertSummary.hidden=true}
});

var showing=false;
pwToggle.addEventListener('click',function(){
showing=!showing;
pwInput.type=showing?'text':'password';
cpwInput.type=showing?'text':'password';
pwToggle.textContent=showing?'Hide':'Show';
pwToggle.setAttribute('aria-label',showing?'Hide password':'Show password');
});
})();
</script>
